&lt;div class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot; data-offset-key=&quot;d4k7b-0-0&quot;&gt;&lt;span data-offset-key=&quot;d4k7b-0-0&quot;&gt;&lt;span data-text=&quot;true&quot;&gt;Experience with AI integration in cybersecurity solutions&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
&lt;/li&gt;
&lt;li class=&quot;public-DraftStyleDefault-unorderedListItem public-DraftStyleDefault-depth0 public-DraftStyleDefault-listLTR&quot; data-block=&quot;true&quot; data-editor=&quot;5tqm&quot; data-offset-key=&quot;djiqm-0-0&quot;&gt;
&lt;div class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot; data-offset-key=&quot;djiqm-0-0&quot;&gt;&lt;span data-offset-key=&quot;djiqm-0-0&quot;&gt;&lt;span data-text=&quot;true&quot;&gt;Proficiency in cybersecurity sales tools and CRM software&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
&lt;/li&gt;
&lt;li class=&quot;public-DraftStyleDefault-unorderedListItem public-DraftStyleDefault-depth0 public-DraftStyleDefault-listLTR&quot; data-block=&quot;true&quot; data-editor=&quot;5tqm&quot; data-offset-key=&quot;7n11u-0-0&quot;&gt;
