&lt;div class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot; data-offset-key=&quot;84ho5-0-0&quot;&gt;&lt;span data-offset-key=&quot;84ho5-0-0&quot;&gt;&lt;span data-text=&quot;true&quot;&gt;Knowledge of security operations and incident response processes&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
